import numpy as np
import math

def private_histogram(data, epsilon, rng):
    categories = ["A", "B", "C"]
    counts = {cat: 0 for cat in categories}

    if data is not None:
        for item in data:
            if item in counts:
                counts[item] += 1

    # Sensitivity Delta f = 1 since adding/removing one record 
    # changes exactly one bin count by 1.
    scale = 1.0 / epsilon
    noise = rng.laplace(0, scale, len(categories))

    return {cat: float(counts[cat] + noise[i]) for i, cat in enumerate(categories)}

import numpy as np
import math

def randomized_response(data, epsilon, rng):
    bit = data[0]
    p = math.exp(epsilon) / (1 + math.exp(epsilon))
    if rng.random() < p:
        return bit
    else:
        return 1 - bit
